from django.db import migrations, models

# Cuenta puente de las comisiones que Openpay descuenta de cada depósito: el
# gasto y el IVA acreditable los registra su factura mensual. Idempotente.
CODIGO = '106.02'
NOMBRE = 'Comisiones Openpay por comprobar'


def crear_cuenta(apps, schema_editor):
    CuentaContable = apps.get_model('contabilidad', 'CuentaContable')
    ConfiguracionContable = apps.get_model('contabilidad', 'ConfiguracionContable')

    padre = CuentaContable.objects.filter(codigo_sat='106').first()
    if padre is None:
        print("Cuenta 106 no encontrada: no se creó 106.02 para COMISIONES_POR_COMPROBAR")
        return
    cuenta, _ = CuentaContable.objects.get_or_create(
        codigo_sat=CODIGO,
        defaults={
            'nombre': NOMBRE, 'tipo': 'ACTIVO', 'naturaleza': 'D',
            'nivel': 3, 'padre': padre, 'permite_movimientos': True,
        },
    )
    ConfiguracionContable.objects.get_or_create(
        operacion='COMISIONES_POR_COMPROBAR',
        defaults={'cuenta': cuenta, 'descripcion': NOMBRE, 'activa': True},
    )


def revertir(apps, schema_editor):
    ConfiguracionContable = apps.get_model('contabilidad', 'ConfiguracionContable')
    ConfiguracionContable.objects.filter(operacion='COMISIONES_POR_COMPROBAR').delete()


